contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");

        c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeOwnerBal = address(this).balance;
        uint beforeContractBal = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint afterOwnerBal = address(this).balance;
        uint afterContractBal = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(afterOwnerBal == beforeOwnerBal + beforeContractBal && afterContractBal == 0 && afterCount == beforeCount);
    }

    receive() external payable {}
}

